ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/(vssadmin|wbadmin|wevtutil|bcdedit|powershell|pwsh|sc|net)\.exe$/i
| regex("(?i)(delete\\s+shadows|delete\\s+catalog|wevtutil\\s+cl|disablerealtimemonitoring|stop\\s+(WinDefend|Sense)|add-mppreference\\s+-exclusionpath|safeboot|recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures)", field=CommandLine)
| case {
    regex("(?i)delete\\s+shadows|delete\\s+catalog", field=CommandLine) | sig:="vss_delete";
    regex("(?i)wevtutil\\s+cl|clear-eventlog", field=CommandLine) | sig:="log_wipe";
    regex("(?i)disablerealtimemonitoring|stop\\s+(WinDefend|Sense)|exclusionpath", field=CommandLine) | sig:="defender_off";
    regex("(?i)safeboot|recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures", field=CommandLine) | sig:="recovery_off";
    * | sig:="other";
  }
| groupBy([aid, ComputerName, UserName], function=[count(sig, distinct=true, as=stage_count), collect([sig, CommandLine, ParentBaseFileName], multival=true), min(_time, as=first_seen), max(_time, as=last_seen)])
| stage_count >= 3
| sort(first_seen, order=desc)
